:root {
  --brand: #1a6fe0;
  --brand-dark: #14539f;
  --brand-soft: #e8f1fd;
  --bg: #f2f6fc;
  --surface: #ffffff;
  --text: #16233a;
  --text-muted: #5b6b85;
  --border: #d5e0f0;
  --danger: #d64545;
  --danger-soft: #fdecec;
  --radius: 14px;
  --shadow: 0 6px 18px rgba(26, 111, 224, 0.10);
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, #eaf2fe 0%, var(--bg) 45%, #eef4fd 100%);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-text-size-adjust: 100%;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 760px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  min-height: 100vh;
}

.app-header {
  padding: 8px 4px 16px;
}

.app-title {
  margin: 0;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--brand-dark);
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text-muted);
}

/* 统计 */
.stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 16px;
}

.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 6px;
  text-align: center;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-label {
  font-size: 12px;
  color: var(--text-muted);
  white-space: nowrap;
}

.stat-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--brand);
}

.stat-card[data-stat="all"] .stat-value {
  color: var(--brand-dark);
}

/* 工具栏 */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-btn {
  appearance: none;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-muted);
  border-radius: 999px;
  padding: 7px 14px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.filter-btn:hover {
  border-color: var(--brand);
  color: var(--brand);
}

.filter-btn.is-active {
  background: var(--brand);
  border-color: var(--brand);
  color: #fff;
  font-weight: 600;
}

.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 18px;
  font-size: 14px;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, opacity 0.15s;
}

.btn-primary {
  background: var(--brand);
  color: #fff;
}

.btn-primary:hover {
  background: var(--brand-dark);
}

.btn-ghost {
  background: var(--surface);
  color: var(--text-muted);
  border-color: var(--border);
}

.btn-ghost:hover {
  color: var(--brand);
  border-color: var(--brand);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover {
  background: #b93a3a;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* 列表 */
.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid var(--brand);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.record-card[data-stage="待投递"] { border-left-color: #7f9dc4; }
.record-card[data-stage="已投递"] { border-left-color: var(--brand); }
.record-card[data-stage="面试中"] { border-left-color: #f0a020; }
.record-card[data-stage="已结束"] { border-left-color: #9aa7b8; }

.record-top {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
  justify-content: space-between;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 14px;
  color: var(--brand-dark);
  word-break: break-word;
}

.stage-badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--brand-soft);
  color: var(--brand-dark);
  white-space: nowrap;
}

.stage-badge[data-stage="待投递"] { background: #eef2f8; color: #4d6484; }
.stage-badge[data-stage="已投递"] { background: var(--brand-soft); color: var(--brand-dark); }
.stage-badge[data-stage="面试中"] { background: #fdf3e0; color: #a86a00; }
.stage-badge[data-stage="已结束"] { background: #eef1f5; color: #6b7789; }

.record-meta {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text-muted);
}

.record-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text);
  background: #f7faff;
  border: 1px dashed var(--border);
  border-radius: 10px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  justify-content: flex-end;
}

.record-actions .btn {
  padding: 7px 14px;
  font-size: 13px;
}

.empty-hint {
  margin: 28px 0;
  text-align: center;
  color: var(--text-muted);
  font-size: 14px;
}

/* 弹窗 */
.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(18, 34, 58, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.modal-mask[hidden] {
  display: none;
}

.modal {
  width: 100%;
  max-width: 460px;
  max-height: 90vh;
  overflow-y: auto;
  background: var(--surface);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 18px 40px rgba(18, 34, 58, 0.28);
}

.modal-title {
  margin: 0 0 14px;
  font-size: 18px;
  color: var(--brand-dark);
}

.confirm-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text);
  word-break: break-word;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
}

.req {
  color: var(--danger);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font-family: inherit;
  font-size: 15px;
  color: var(--text);
  background: #fbfdff;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.field textarea {
  resize: vertical;
  min-height: 72px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(26, 111, 224, 0.15);
}

.form-error {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid #f3c9c9;
  border-radius: 10px;
  padding: 8px 10px;
}

.form-error[hidden] {
  display: none;
}

.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 4px;
}

@media (max-width: 480px) {
  .app-shell {
    padding: 16px 12px 40px;
  }

  .app-title {
    font-size: 21px;
  }

  .stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .filters {
    justify-content: flex-start;
  }

  .toolbar .btn-primary {
    width: 100%;
  }

  .modal-actions .btn {
    flex: 1;
  }
}

