    if (!da && db) return 1;
    return 0;
  });
}

function showGlobalError(msg) {
  if (!msg) {
    globalErrorEl.hidden = true;
    globalErrorEl.textContent = "";
    return;
  }
  globalErrorEl.hidden = false;
  globalErrorEl.textContent = msg;
}

function showFormError(msg) {
  if (!msg) {
    formErrorEl.hidden = true;
    formErrorEl.textContent = "";
    return;
  }
  formErrorEl.hidden = false;
  formErrorEl.textContent = msg;
}

function renderStats() {
  const counts = { 全部: records.length };
  STAGES.forEach((s) => {
    counts[s] = 0;
  });
  records.forEach((r) => {
    const s = normalizeStage(r.stage);
    counts[s] = (counts[s] || 0) + 1;
  });
  Object.keys(statValues).forEach((key) => {
    const el = statValues[key];
    if (el) el.textContent = String(counts[key] || 0);
  });
}

function renderFilters() {
  filterBtns.forEach((btn) => {
    const value = btn.getAttribute("data-filter");
    const active = value === activeFilter;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function renderSearch() {
  if (searchInput.value !== searchKeyword) {
    searchInput.value = searchKeyword;
  }
  clearSearchBtn.hidden = searchKeyword === "";
}

function buildRecordCard(rec) {
  const li = document.createElement("li");
  li.className = "record-card";
  li.setAttribute("data-stage", rec.stage);
  li.setAttribute("data-id", rec.id);

  const top = document.createElement("div");
  top.className = "record-top";

  const titleWrap = document.createElement("div");
  const company = document.createElement("h3");
  company.className = "record-company";
  company.textContent = rec.company || "（未填写公司）";
  const position = document.createElement("p");
  position.className = "record-position";
  position.textContent = rec.position || "（未填写岗位）";
  titleWrap.appendChild(company);
  titleWrap.appendChild(position);

  const badge = document.createElement("span");
  badge.className = "stage-badge";
  badge.setAttribute("data-stage", rec.stage);
  badge.textContent = rec.stage;

  top.appendChild(titleWrap);
  top.appendChild(badge);
  li.appendChild(top);

  const meta = document.createElement("p");
  meta.className = "record-meta";
  meta.textContent = "投递日期：" + (rec.applyDate || "未填写");
  li.appendChild(meta);

  if (rec.note) {
    const note = document.createElement("p");
    note.className = "record-note";
    note.textContent = rec.note;
    li.appendChild(note);
  }

  const actions = document.createElement("div");
  actions.className = "record-actions";

  const editBtn = document.createElement("button");
  editBtn.type = "button";
  editBtn.className = "btn btn-ghost";
  editBtn.textContent = "编辑";
  editBtn.addEventListener("click", () => openForm(rec.id));

  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "btn btn-danger";
  delBtn.textContent = "删除";
  delBtn.addEventListener("click", () => askDelete(rec.id));

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const keyword = searchKeyword.trim().toLowerCase();
  let visible = records;
  if (activeFilter !== "全部") {
    visible = visible.filter((r) => normalizeStage(r.stage) === activeFilter);
  }
  if (keyword) {
    visible = visible.filter((r) => (r.company || "").toLowerCase().indexOf(keyword) !== -1);
  }

  listEl.textContent = "";
  const sorted = sortRecords(visible);
  sorted.forEach((rec) => {
    listEl.appendChild(buildRecordCard(rec));
  });

  if (sorted.length === 0) {
    emptyHintEl.hidden = false;
    if (records.length === 0) {
      emptyHintEl.textContent = "还没有投递记录，点击「新增投递」开始记录吧。";
    } else if (keyword) {
      emptyHintEl.textContent = "没有找到公司名称包含「" + searchKeyword.trim() + "」的记录。";
    } else {
      emptyHintEl.textContent = "当前阶段下暂无记录。";
    }
  } else {
    emptyHintEl.hidden = true;
    emptyHintEl.textContent = "";
  }
}

function renderAll() {
  renderStats();
  renderFilters();
  renderSearch();
  renderList();
}

function openForm(id) {
  editingId = id || null;
  showFormError("");
  if (editingId) {
    const rec = records.find((r) => r.id === editingId);
    if (!rec) {
      editingId = null;
      return;
    }
    formTitleEl.textContent = "编辑投递";
    fieldCompany.value = rec.company;
    fieldPosition.value = rec.position;
    fieldDate.value = rec.applyDate || "";
    fieldStage.value = normalizeStage(rec.stage);
    fieldNote.value = rec.note;
  } else {
    formTitleEl.textContent = "新增投递";
    fieldCompany.value = "";
    fieldPosition.value = "";
    fieldDate.value = todayStr();
    fieldStage.value = "待投递";
    fieldNote.value = "";
  }
  formMask.hidden = false;
  fieldCompany.focus();
}

function closeForm() {
  formMask.hidden = true;
  editingId = null;
  showFormError("");
}

function askDelete(id) {
  const rec = records.find((r) => r.id === id);
  if (!rec) return;
  pendingDeleteId = id;
  confirmTextEl.textContent = "确定要删除「" + (rec.company || "未填写公司") + " · " + (rec.position || "未填写岗位") + "」这条投递记录吗？此操作不可撤销。";
  confirmMask.hidden = false;
}

function closeConfirm() {
  confirmMask.hidden = true;
  pendingDeleteId = null;
}

async function persist(nextRecords) {
  const state = await appStore.getState();
  const base = state && typeof state === "object" ? state : {};
  const next = Object.assign({}, base);
  next.records = nextRecords;
  await appStore.setState(next);
}

async function handleSubmit(event) {
  event.preventDefault();
  if (saving) return;

  const company = fieldCompany.value.trim();
  const position = fieldPosition.value.trim();
  const applyDate = fieldDate.value || "";
  const stage = normalizeStage(fieldStage.value);
  const note = fieldNote.value.trim();

  if (!company) {
    showFormError("请填写公司名称。");
    fieldCompany.focus();
    return;
  }
  if (!position) {
    showFormError("请填写应聘岗位。");
    fieldPosition.focus();
    return;
  }

  showFormError("");
  const previous = records;
  let nextRecords;

  if (editingId) {
    nextRecords = records.map((r) => {
      if (r.id !== editingId) return r;
      return Object.assign({}, r, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note
      });
    });
  } else {
    const rec = normalizeRecord({
      id: makeId(),
      company: company,
      position: position,
      applyDate: applyDate,
      stage: stage,
      note: note
    });
    nextRecords = records.concat([rec]);
  }

  saving = true;
  submitBtn.disabled = true;
  try {
    await persist(nextRecords);
    records = nextRecords;
    showGlobalError("");
    closeForm();
    renderAll();
  } catch (err) {
    records = previous;
    showFormError("保存失败，请重试。你的输入已保留。");
    renderAll();
  } finally {
    saving = false;
    submitBtn.disabled = false;
  }
}

async function handleConfirmDelete() {
  if (!pendingDeleteId) return;
  const id = pendingDeleteId;
  const previous = records;
  const nextRecords = records.filter((r) => r.id !== id);

  try {
    await persist(nextRecords);
    records = nextRecords;
    showGlobalError("");
    closeConfirm();
    renderAll();
  } catch (err) {
    records = previous;
    closeConfirm();
    showGlobalError("删除失败，请重试。");
    renderAll();
  }
}

async function init() {
  const state = await appStore.getState();
  const base = state && typeof state === "object" ? state : {};
  const rawList = Array.isArray(base.records) ? base.records : [];
  records = rawList.map(normalizeRecord);

  filterBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      activeFilter = btn.getAttribute("data-filter") || "全部";
      renderAll();
    });
  });

  searchInput.addEventListener("input", () => {
    searchKeyword = searchInput.value;
    renderSearch();
    renderList();
  });

  clearSearchBtn.addEventListener("click", () => {
    searchKeyword = "";
    searchInput.value = "";
    renderSearch();
    renderList();
    searchInput.focus();
  });

  document.querySelector('[data-action="open-create"]').addEventListener("click", () => openForm(null));
  document.querySelector('[data-action="cancel-form"]').addEventListener("click", closeForm);
  document.querySelector('[data-action="cancel-delete"]').addEventListener("click", closeConfirm);
  document.querySelector('[data-action="confirm-delete"]').addEventListener("click", handleConfirmDelete);

  formEl.addEventListener("submit", handleSubmit);

  formMask.addEventListener("click", (e) => {
    if (e.target === formMask) closeForm();
  });
  confirmMask.addEventListener("click", (e) => {
    if (e.target === confirmMask) closeConfirm();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (!confirmMask.hidden) {
      closeConfirm();
    } else if (!formMask.hidden) {
      closeForm();
    }
  });

  renderAll();
}

await init();

